const input = $input.first().json.body ?? $input.first().json;
const stringFields = ['event', 'run', 'source', 'sourceJob', 'action', 'token'];
const forbidden = /(?:private|cv|profile|prompt|credential|password|secret|api[_-]?key|authorization)/i;
const fail = (reason) => { throw new Error(`invalid feedback: ${reason}`); };
if (!input || typeof input !== 'object' || Array.isArray(input)) fail('object required');
if (JSON.stringify(input).length > 2048 || forbidden.test(JSON.stringify(input))) fail('disallowed content');
const allowedFields = new Set(['schema_version', 'event', 'run', 'source', 'sourceJob', 'action', 'token', 'expiry']);
if (Object.keys(input).some((field) => !allowedFields.has(field))) fail('unknown field');
if (input.schema_version !== 1) fail('schema_version');
if (input.event !== 'job_feedback') fail('event');
if (Array.isArray(input.action)) fail('duplicate action');
for (const field of stringFields) {
  if (typeof input[field] !== 'string' || input[field].length < 1 || input[field].length > 128) fail(field);
}
if (!['applied', 'dismissed', 'interesting'].includes(input.action)) fail('action');
if (!Number.isSafeInteger(input.expiry) || input.expiry < 0 || input.expiry > 4102444800) fail('expiry');
if (!/^[A-Za-z0-9_-]{8,128}\.[0-9]{10}$/.test(input.token) || !input.token.endsWith(`.${input.expiry}`)) fail('token');
if (input.expiry <= Math.floor(Date.now() / 1000)) fail('expired token');
const state = $getWorkflowStaticData('global');
const MAX_REPLAY_ENTRIES = 1024;
const now = Date.now();
state.replayedTokens = state.replayedTokens && typeof state.replayedTokens === 'object' ? state.replayedTokens : {};
for (const [key, entry] of Object.entries(state.replayedTokens)) {
  if (!entry || entry.expiresAt <= now) delete state.replayedTokens[key];
}
const replayKey = input.token;
if (state.replayedTokens[replayKey]) fail('replay');
if (Object.keys(state.replayedTokens).length >= MAX_REPLAY_ENTRIES) {
  const oldestKey = Object.keys(state.replayedTokens).sort((left, right) => {
    const seenAtDelta = state.replayedTokens[left].seenAt - state.replayedTokens[right].seenAt;
    return seenAtDelta || left.localeCompare(right);
  })[0];
  delete state.replayedTokens[oldestKey];
}
state.replayedTokens[replayKey] = {
  seenAt: now,
  expiresAt: input.expiry * 1000,
};
return [{ json: { accepted: true, event: 'job_feedback', schema_version: 1, run: input.run, source: input.source, sourceJob: input.sourceJob, action: input.action } }];
